use super::kit::*;
pub fn commands()->Vec<Command>{vec![
Command{name:"inspect_asc_cdl",description:"Strict bounded.cc/.cdl parse with IDs,SOP,saturation,descriptions. Limited inlineCDLprofile, noDTD/entities/externalrefs. No gradeapplication.",mutates:false,schema:obj(vec![("path",s(".cc/.cdl"))],&["path"]),run:|_,a|serde_json::to_value(crate::color::cdl_xml::Collection::read(str_arg(a,"path")?)?).map_err(|e|e.to_string())},
Command{name:"export_asc_cdl",description:"Canonicalsemantic.cc/.cdl export from importedfile or savedasc_cdl effect. Preservesnumbers,ID,supporteddescriptions, notXMLbytes/order. Noapply/defaults.",mutates:false,schema:obj(vec![("source_path",s("importedfile optional")),("clip_id",s("effectclip optional")),("effect_id",s("effectid optional")),("path",s("output.cc/.cdl")),("id",s("selectcorrection optional"))],&["path"]),run:|ss,a|{let c=if let Some(path)=a.get("source_path").and_then(Value::as_str){let c=crate::color::cdl_xml::Collection::read(path)?;if let Some(id)=a.get("id").and_then(Value::as_str){crate::color::cdl_xml::Collection{corrections:vec![c.select(Some(id))?.clone()]}}else{c}}else{let clip=ss.project.find_clip(str_arg(a,"clip_id")?).ok_or("noclip")?;let e=clip.effects.iter().find(|e|e.id==str_arg(a,"effect_id").unwrap_or("")&&e.kind=="asc_cdl").ok_or("noasc_cdleffect")?;crate::color::cdl_xml::Collection{corrections:vec![serde_json::from_str(e.strings.get("cdl_payload").ok_or("missingpayload")?).map_err(|e|e.to_string())?]}};let path=str_arg(a,"path")?;let single=path.to_lowercase().ends_with(".cc");if !single&&!path.to_lowercase().ends_with(".cdl"){return Err("requires.cc/.cdl".into())}let xml=c.xml(single)?;std::fs::write(path,xml).map_err(|e|e.to_string())?;Ok(json!({"path":path,"corrections":c.corrections.len(),"semantic_roundtrip":true}))}},
Command{name:"apply_asc_cdl",description:"Import selectedASC CDL as frozen nativeOCIOCDL_ASC effect. Encodingexplicitcurrent or managedACEScct/AP1. NoexternalFileTransform; immutablepayload survives filechanges. ClampSOP/sat perASCstyle.",mutates:true,schema:obj(vec![("clip_id",s("clip")),("path",s(".cc/.cdl")),("id",s("requiredifmultiple")),("encoding",json!({"type":"string","enum":["current","ACEScct"]})),("config_path",s("ACEScct: self-containedOCIOconfig")),("linear_space",s("ACEScct:AP1space")),("cct_space",s("ACEScctspace"))],&["clip_id","path","encoding"]),run:|ss,a|{
 #[cfg(not(feature="native-ocio"))]{let _=(ss,a);Err("nativeASC CDL requiresnative-ocio+OCIO2".into())}
 #[cfg(feature="native-ocio")]{let id=str_arg(a,"clip_id")?.to_string();if ss.project.find_clip(&id).is_none(){return Err("noclip".into())}let c=crate::color::cdl_xml::Collection::read(str_arg(a,"path")?)?;let c=c.select(a.get("id").and_then(Value::as_str))?;crate::color::ocio_config::Processor::cdl(c)?;let encoding=str_arg(a,"encoding")?;let mut strings=std::collections::BTreeMap::new();strings.insert("cdl_payload".into(),serde_json::to_string(c).map_err(|e|e.to_string())?);let mut params=crate::effects::Params::new();if encoding=="ACEScct"{if !ss.project.color_pipeline.enabled||ss.project.color_pipeline.working_gamut!=3{return Err("ACEScctCDL requiresmanagedAP1".into())}let config=crate::color::ocio_config::Config::from_file(str_arg(a,"config_path")?)?;config.processor(str_arg(a,"linear_space")?,str_arg(a,"cct_space")?)?;config.processor(str_arg(a,"cct_space")?,str_arg(a,"linear_space")?)?;for k in ["config_path","linear_space","cct_space"]{strings.insert(k.into(),str_arg(a,k)?.into());}strings.insert("bound_linear_gamut".into(),"3".into());params.insert("gamut".into(),crate::keyframe::Prop::new(3.));}else if encoding!="current"{return Err("encodingcurrent/ACEScct".into())}let fx=ss.project.gen_id("fx");ss.project.find_clip_mut(&id).unwrap().effects.push(crate::model::Effect{id:fx.clone(),kind:"asc_cdl".into(),params,strings});Ok(json!({"effect_id":fx,"cdl_id":c.id,"encoding":encoding,"style":"CDL_ASC","file_dependency":false}))}
}}]}
